/**
 * Classify a resolved sendMail result for one recipient. The result is untrusted (D4): it is read through safeRead, its lists
 * are bounded, and a result that cannot be interpreted is UNKNOWN — the message was handed over, so neither acceptance nor
 * refusal is established. R2 (E2): "failed" requires the recipient to be LISTED in `rejected` (and not in `accepted`); a
 * well-formed result that lists it nowhere — e.g. { accepted: [], rejected: [], response: "250 OK" } — establishes neither
 * outcome and is UNKNOWN (`provider_result_indeterminate`).
 */
export function classifyTransportInfo(info, to) {
  const norm = (x) => {
    const v = x !== null && typeof x === "object" ? safeRead(x, "address") : x;
    return typeof v === "string" && v.length <= MAX_ADDRESS ? v.trim().toLowerCase() : null;
  };
  const listOf = (k, required) => {
    const v = safeRead(info, k);
    if (v === undefined) return required ? null : [];
    try {                            // a hostile list (revoked Proxy, throwing length / index getters) proves nothing
      if (!Array.isArray(v) || v.length > MAX_LISTED) return null;
      const out = [];
      for (let i = 0; i < v.length; i++) {
        const n = norm(v[i]);
        if (n === null) return null; // an entry that cannot be read might have been this recipient: the list proves nothing
        out.push(n);
      }
      return out;
    } catch { return null; }
  };
  const rc = responseTextCode(safeRead(info, "response"));
  const want = norm(to);
  const accepted = listOf("accepted", true), rejected = listOf("rejected", false);
  if (info === null || typeof info !== "object" || accepted === null || rejected === null || want === null)
    return { outcome: "unknown", code: "provider_result_malformed", responseCode: rc };
  const isAccepted = accepted.includes(want), isRejected = rejected.includes(want);
  // contradictory answers (listed both ways, or "accepted" with a non-2xx reply code) do not establish either outcome
  if ((isAccepted && isRejected) || (isAccepted && rc !== null && rc >= 300)) return { outcome: "unknown", code: "provider_result_inconsistent", responseCode: rc };
  if (isRejected) return { outcome: "failed", retryable: false, inRunRetry: false, code: "provider_rejected_recipient", responseCode: rc };
  if (!isAccepted) return { outcome: "unknown", code: "provider_result_indeterminate", responseCode: rc };
  return { outcome: "accepted", responseCode: rc };
}

