/**
 * Classify a resolved sendMail result for one recipient. The result is untrusted (D4): it is read through safeRead, its lists
 * are bounded, and a result that cannot be interpreted is UNKNOWN — the message was handed over, so neither acceptance nor
 * refusal is established.
 *
 * R3 (review E2 continuation): the fields are judged TOGETHER against the provider contract of the configured adapter
 * (lib/sendEmail.js: one recipient, nodemailer 6.x SMTP — lib/smtp-connection/index.js). For that adapter a RESOLVED result
 * exists only after the server answered the end of DATA with 2xx (`_actionSMTPStream`); DATA is sent only when the sole RCPT
 * was accepted (`_actionRCPT`), and every refusal — MAIL FROM, RCPT TO, DATA — reaches us as a REJECTED promise
 * (EENVELOPE / EMESSAGE), classified by classifyTransportError. So:
 *   accepted  ONLY when every field agrees: the recipient is listed in `accepted`, `accepted` names no other address,
 *             `rejected` and `rejectedErrors` are empty, the reply code (when present) is 2xx, `envelope.to` (when present)
 *             is exactly the recipient.
 *   failed    (provider_rejected_recipient, final, never retried) ONLY for a fully consistent refusal: the recipient is the
 *             only address in `rejected`, `accepted` is empty, the reply code is PRESENT and 4xx/5xx, `rejectedErrors` (when
 *             present) agree with it, `envelope.to` (when present) is exactly the recipient. No list and no code alone
 *             establishes a refusal.
 *   unknown   everything else: unreadable fields (provider_result_malformed), fields that contradict each other or the
 *             single-recipient envelope — e.g. the recipient rejected beside a 250 end-of-DATA reply, or another address
 *             accepted (provider_result_inconsistent), a refusal without a reply code (provider_result_incomplete), or a result
 *             that lists the recipient nowhere (provider_result_indeterminate). Unknown is held: never re-sent automatically.
 */
export function classifyTransportInfo(info, to) {
  const norm = (x) => {
    const v = x !== null && typeof x === "object" ? safeRead(x, "address") : x;
    return typeof v === "string" && v.length <= MAX_ADDRESS ? v.trim().toLowerCase() : null;
  };
  const listOf = (obj, k, required) => {
    const v = safeRead(obj, k);
    if (v === undefined) return required ? null : [];
    try {                            // a hostile list (revoked Proxy, throwing length / index getters) proves nothing
      if (!Array.isArray(v) || v.length > MAX_LISTED) return null;
      const out = [];
      for (let i = 0; i < v.length; i++) {
        const n = norm(v[i]);
        if (n === null) return null; // an entry that cannot be read might have been this recipient: the list proves nothing
        out.push(n);
      }
      return out;
    } catch { return null; }
  };
  const malformed = (rc) => ({ outcome: "unknown", code: "provider_result_malformed", responseCode: rc });
  const inconsistent = (rc) => ({ outcome: "unknown", code: "provider_result_inconsistent", responseCode: rc });
  if (info === null || typeof info !== "object") return malformed(null);
  // the reply text: absent, or a string that starts with a reply code; anything else is unreadable
  const response = safeRead(info, "response");
  const rc = responseTextCode(response);
  if (response !== undefined && rc === null) return malformed(null);
  const want = norm(to);
  const accepted = listOf(info, "accepted", true), rejected = listOf(info, "rejected", false);
  if (accepted === null || rejected === null || want === null) return malformed(rc);
  // per-recipient refusal details: absent, or a bounded list of readable { responseCode, recipient } records
  const errs = safeRead(info, "rejectedErrors");
  let rejectedErrors = [];
  if (errs !== undefined) {
    try {
      if (!Array.isArray(errs) || errs.length > MAX_LISTED) return malformed(rc);
      rejectedErrors = [];
      for (let i = 0; i < errs.length; i++) {
        const e = errs[i];
        const erc = safeRead(e, "responseCode"), rcp = safeRead(e, "recipient");
        rejectedErrors.push({ responseCode: erc === undefined ? null : providerResponseCode(erc), badCode: erc !== undefined && providerResponseCode(erc) === null,
          recipient: rcp === undefined ? undefined : norm(rcp) });
      }
    } catch { return malformed(rc); }
  }
  // the envelope the adapter reports: absent, or exactly this one recipient
  const envelope = safeRead(info, "envelope");
  if (envelope !== undefined) {
    const envTo = listOf(envelope, "to", false);
    if (envTo === null) return malformed(rc);
    if (envTo.length > 0 && (envTo.length !== 1 || envTo[0] !== want)) return inconsistent(rc);
  }
  const isAccepted = accepted.includes(want), isRejected = rejected.includes(want);
  const otherAccepted = accepted.some((a) => a !== want), otherRejected = rejected.some((a) => a !== want);
  const rc2xx = rc !== null && rc >= 200 && rc < 300, rcNegative = rc !== null && rc >= 400;
  // another accepted address contradicts a one-recipient envelope, whatever else is listed
  if (otherAccepted) return inconsistent(rc);
  if (isAccepted) {
    if (isRejected || otherRejected || rejectedErrors.length > 0 || (rc !== null && !rc2xx)) return inconsistent(rc);
    return { outcome: "accepted", responseCode: rc };
  }
  if (isRejected) {
    if (otherRejected || accepted.length > 0) return inconsistent(rc);
    if (rc === null) return { outcome: "unknown", code: "provider_result_incomplete", responseCode: null };
    if (!rcNegative) return inconsistent(rc);   // e.g. rejected beside the 250 end-of-DATA reply: impossible for one recipient
    for (const e of rejectedErrors)
      if (e.badCode || (e.responseCode !== null && e.responseCode !== rc) || e.recipient === null || (e.recipient !== undefined && e.recipient !== want)) return inconsistent(rc);
    return { outcome: "failed", retryable: false, inRunRetry: false, code: "provider_rejected_recipient", responseCode: rc };
  }
  return { outcome: "unknown", code: "provider_result_indeterminate", responseCode: rc };
}
